\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{regionBlue}{HTML}{D4E8FF}
\path[fill=regionBlue] plot[domain=pi/4:pi/2,samples=40] (\x,{sin(\x r)}) -- plot[domain=pi/2:pi/4,samples=40] (\x,{cos(\x r)}) -- cycle;
\draw[->,black,line width=.5pt](-1,0)--(4.15,0)node[right]{$x$};
