\draw[<->,black,line width=.8pt,domain=-.85:3.85,samples=100]plot(\x,{sin(\x r)});
\draw[<->,black,line width=.8pt,domain=-.85:3.85,samples=100]plot(\x,{cos(\x r)});
\draw[black,line width=.4pt]({pi/2},0)--({pi/2},1);
\foreach \v/\t in {.785398/\frac{\pi}{4},1.570796/\frac{\pi}{2},3.141593/\pi}{\draw[black,line width=.4pt](\v,.05)--(\v,-.05);\node[below]at(\v,-.06){\special{dvisvgm:raw <g data-graph-text="tick">}$\t$\special{dvisvgm:raw </g>}};}
